<?php
$pageTitle='Resources';
$canManage=in_array(user()['role'],['admin','project_manager','site_supervisor'],true);
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $action=(string)($_POST['action']??'');
    if ($action==='resource_delete') {
        require_role(['admin','project_manager']); $id=(int)($_POST['id']??0); $st=$pdo->prepare('DELETE FROM resources WHERE id=?');$st->execute([$id]);flash('success','Resource deleted.');redirect('index.php?page=resources');
    }
    if(in_array($action,['resource_create','resource_update'],true)){
        require_role(['admin','project_manager','site_supervisor']);$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$type=(string)($_POST['resource_type']??'other');$unit=trim((string)($_POST['unit']??'unit'));$qty=filter_var($_POST['quantity_available']??null,FILTER_VALIDATE_FLOAT);$notes=trim((string)($_POST['notes']??''));
        if($name===''||$qty===false||$qty<0){flash('error','Enter a resource name and a non-negative quantity.');redirect('index.php?page=resources');}
        if(!in_array($type,['labour','equipment','material','other'],true))$type='other';if($unit==='')$unit='unit';
        if($action==='resource_create'){$st=$pdo->prepare('INSERT INTO resources(name,resource_type,unit,quantity_available,notes,created_by) VALUES(?,?,?,?,?,?)');$st->execute([$name,$type,$unit,$qty,$notes?:null,(int)user()['id']]);flash('success','Resource recorded.');}
        else{$st=$pdo->prepare('UPDATE resources SET name=?,resource_type=?,unit=?,quantity_available=?,notes=? WHERE id=?');$st->execute([$name,$type,$unit,$qty,$notes?:null,$id]);flash('success','Resource updated.');}redirect('index.php?page=resources');
    }
    if($action==='allocate'){
        require_role(['admin','project_manager','site_supervisor']);$taskId=(int)($_POST['task_id']??0);$resourceId=(int)($_POST['resource_id']??0);$qty=filter_var($_POST['quantity_assigned']??null,FILTER_VALIDATE_FLOAT);$notes=trim((string)($_POST['allocation_notes']??''));
        if($qty===false||$qty<=0){flash('error','Allocation quantity must be greater than zero.');redirect('index.php?page=resources');}
        $st=$pdo->prepare('SELECT quantity_available FROM resources WHERE id=?');$st->execute([$resourceId]);$capacity=$st->fetchColumn();
        $st=$pdo->prepare('SELECT id FROM tasks WHERE id=?');$st->execute([$taskId]);if($capacity===false || !$st->fetchColumn()){flash('error','Choose a valid resource and task.');redirect('index.php?page=resources');}
        $st=$pdo->prepare('SELECT COALESCE(SUM(quantity_assigned),0) FROM task_resources WHERE resource_id=? AND task_id<>?');$st->execute([$resourceId,$taskId]);$used=(float)$st->fetchColumn();
        if($used+(float)$qty>(float)$capacity){flash('error','That allocation exceeds the recorded resource quantity available after existing allocations.');redirect('index.php?page=resources');}
        $st=$pdo->prepare('INSERT INTO task_resources(task_id,resource_id,quantity_assigned,notes,assigned_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE quantity_assigned=VALUES(quantity_assigned),notes=VALUES(notes),assigned_by=VALUES(assigned_by)');$st->execute([$taskId,$resourceId,$qty,$notes?:null,(int)user()['id']]);flash('success','Resource allocated to the task.');redirect('index.php?page=resources');
    }
    if($action==='allocation_delete') {require_role(['admin','project_manager','site_supervisor']);$id=(int)($_POST['id']??0);$st=$pdo->prepare('DELETE FROM task_resources WHERE id=?');$st->execute([$id]);flash('success','Resource allocation removed.');redirect('index.php?page=resources');}
}
$edit=null;if(isset($_GET['edit'])&&$canManage){$st=$pdo->prepare('SELECT * FROM resources WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch()?:null;}
$resources=$pdo->query('SELECT r.*, COALESCE((SELECT SUM(tr.quantity_assigned) FROM task_resources tr WHERE tr.resource_id=r.id),0) AS allocated FROM resources r ORDER BY r.name')->fetchAll();
if(is_manager()||user()['role']==='site_supervisor')$tasks=$pdo->query("SELECT t.id,t.title,p.name AS project_name FROM tasks t JOIN projects p ON p.id=t.project_id WHERE t.status<>'completed' ORDER BY p.name,t.title")->fetchAll();else{$st=$pdo->prepare('SELECT t.id,t.title,p.name AS project_name FROM tasks t JOIN projects p ON p.id=t.project_id WHERE t.assigned_to=? AND t.status<>\'completed\' ORDER BY p.name,t.title');$st->execute([(int)user()['id']]);$tasks=$st->fetchAll();}
$allocSql='SELECT tr.*,r.name AS resource_name,r.unit,t.title AS task_title,p.name AS project_name,u.full_name AS assigned_by_name FROM task_resources tr JOIN resources r ON r.id=tr.resource_id JOIN tasks t ON t.id=tr.task_id JOIN projects p ON p.id=t.project_id JOIN users u ON u.id=tr.assigned_by WHERE 1=1';$ap=[];if(!is_manager()&&user()['role']!=='site_supervisor'){$allocSql.=' AND t.assigned_to=?';$ap[]=(int)user()['id'];}$allocSql.=' ORDER BY tr.created_at DESC';$st=$pdo->prepare($allocSql);$st->execute($ap);$allocations=$st->fetchAll();
require __DIR__ . '/../inc/header.php';
?>
<div class="page-toolbar"><p class="muted">Maintain a resource register and allocate materials, equipment or labour to scheduled tasks.</p></div>
<?php if($canManage): ?><section class="panel form-panel"><div class="panel-heading"><div><h3><?= $edit?'Edit resource':'Resource register' ?></h3><p>Record available quantities before allocating them to tasks.</p></div><?php if($edit): ?><a class="text-link" href="index.php?page=resources">Cancel edit</a><?php endif; ?></div><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'resource_update':'resource_create' ?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Resource name *<input name="name" maxlength="160" required value="<?= e($edit['name']??'') ?>" placeholder="Cement, excavator, mason"></label><label>Type<select name="resource_type"><?php foreach(['labour','equipment','material','other'] as $t): ?><option value="<?= e($t) ?>" <?= ($edit['resource_type']??'other')===$t?'selected':'' ?>><?= e(ucfirst($t)) ?></option><?php endforeach; ?></select></label><label>Quantity available *<input type="number" step="0.01" min="0" required name="quantity_available" value="<?= e($edit['quantity_available']??'0') ?>"></label><label>Unit<input name="unit" maxlength="40" value="<?= e($edit['unit']??'unit') ?>" placeholder="bags, hours, people"></label><label class="span-2">Notes<textarea name="notes" rows="2"><?= e($edit['notes']??'') ?></textarea></label><div class="form-actions span-2"><button class="btn btn-primary"><?= $edit?'Save resource':'Add resource' ?></button><?php if($edit): ?><a class="btn btn-outline" href="index.php?page=resources">Cancel</a><?php endif; ?></div></form></section><?php endif; ?>
<section class="panel"><div class="panel-heading"><div><h3>Available resources</h3><p>Available quantity compared with current task allocations.</p></div><span class="count-chip"><?= count($resources) ?> items</span></div><?php if(!$resources): ?><div class="empty-state"><div class="empty-icon">▤</div><h3>No resources recorded</h3><p>Add materials, equipment or labour resources to begin tracking.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Resource</th><th>Type</th><th>Total available</th><th>Allocated</th><th>Remaining</th><?php if($canManage): ?><th>Actions</th><?php endif; ?></tr></thead><tbody><?php foreach($resources as $r): $remaining=(float)$r['quantity_available']-(float)$r['allocated']; ?><tr><td><strong><?= e($r['name']) ?></strong><?php if($r['notes']): ?><small class="cell-sub"><?= e($r['notes']) ?></small><?php endif; ?></td><td><?= e(ucfirst($r['resource_type'])) ?></td><td><?= e(rtrim(rtrim(number_format((float)$r['quantity_available'],2,'.',','),'0'),'.')) ?> <?= e($r['unit']) ?></td><td><?= e(rtrim(rtrim(number_format((float)$r['allocated'],2,'.',','),'0'),'.')) ?> <?= e($r['unit']) ?></td><td><strong class="<?= $remaining<0?'text-danger':'' ?>"><?= e(rtrim(rtrim(number_format($remaining,2,'.',','),'0'),'.')) ?> <?= e($r['unit']) ?></strong></td><?php if($canManage): ?><td class="actions"><a class="action-link" href="index.php?page=resources&edit=<?= (int)$r['id'] ?>">Edit</a><?php if(is_manager()): ?><form method="post" onsubmit="return confirm('Delete resource and its allocations?');"><?= csrf_field() ?><input type="hidden" name="action" value="resource_delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="action-link danger-link">Delete</button></form><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php if($canManage): ?><section class="panel form-panel"><div class="panel-heading"><div><h3>Allocate a resource</h3><p>Assign quantities to a task; allocations are checked against the recorded available quantity.</p></div></div><?php if(!$resources||!$tasks): ?><div class="alert alert-info">You need at least one resource and one unfinished task before making an allocation.</div><?php else: ?><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="allocate"><label class="span-2">Task *<select name="task_id" required><?php foreach($tasks as $t): ?><option value="<?= (int)$t['id'] ?>"><?= e($t['project_name'].' — '.$t['title']) ?></option><?php endforeach; ?></select></label><label>Resource *<select name="resource_id" required><?php foreach($resources as $r): ?><option value="<?= (int)$r['id'] ?>"><?= e($r['name'].' (remaining '.rtrim(rtrim(number_format((float)$r['quantity_available']-(float)$r['allocated'],2,'.',','),'0'),'.').' '.$r['unit'].')') ?></option><?php endforeach; ?></select></label><label>Quantity to allocate *<input type="number" name="quantity_assigned" step="0.01" min="0.01" required></label><label class="span-2">Allocation notes<input name="allocation_notes" maxlength="255" placeholder="Optional usage notes"></label><div class="form-actions span-2"><button class="btn btn-primary">Save allocation</button></div></form><?php endif; ?></section><?php endif; ?>
<section class="panel"><div class="panel-heading"><div><h3>Task resource allocations</h3><p>Current resource assignments.</p></div></div><?php if(!$allocations): ?><div class="empty-inline">No resource allocations have been recorded.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Task / project</th><th>Resource</th><th>Quantity</th><th>Notes</th><th>Action</th></tr></thead><tbody><?php foreach($allocations as $a): ?><tr><td><strong><?= e($a['task_title']) ?></strong><small class="cell-sub"><?= e($a['project_name']) ?></small></td><td><?= e($a['resource_name']) ?></td><td><?= e(rtrim(rtrim(number_format((float)$a['quantity_assigned'],2,'.',','),'0'),'.')) ?> <?= e($a['unit']) ?></td><td><?= e($a['notes']?:'—') ?></td><td class="actions"><?php if($canManage): ?><form method="post" onsubmit="return confirm('Remove this allocation?');"><?= csrf_field() ?><input type="hidden" name="action" value="allocation_delete"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><button class="action-link danger-link">Remove</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require __DIR__ . '/../inc/footer.php'; ?>
